INSERT INTO `shop_listings` (`id`, `inventory_id`, `category_id`, `slug`, `title`, `description`, `description_en`, `price`, `price_original`, `cover_image`, `cover_w`, `cover_h`, `status`, `views`, `created_at`, `updated_at`) VALUES
(120, 120, 1, 'macbook-air-sold-out', 'Macbook Air SOLD OUT', '<ul>\r\n<li>CPU : Intel Core i5 แบบ Dual‑core ความเร็ว 1.6GHz ที่มี Turbo Boost สูงสุด 3.6GHz พร้อมแคช L3 ขนาด 4MB</li>\r\n<li>หน่วยความจำ (RAM) :&nbsp;<span style=\"color: #1d1d1f; font-family: \'SF Pro TH\', \'SF Pro Text\', \'SF Pro Icons\', \'Helvetica Neue\', Helvetica, Arial, sans-serif; font-size: 17px; background-color: #ffffff;\">LPDDR3 ออนบอร์ด ความเร็ว 2133MHz&nbsp; ขนาด 16 GB พื้นที่เก็บข้อมูล (SSD) : ชนิด PCIe ความจุ 128GB </span><span style=\"color: #1d1d1f; font-family: \'SF Pro TH\', \'SF Pro Text\', \'SF Pro Icons\', \'Helvetica Neue\', Helvetica, Arial, sans-serif; font-size: 17px; background-color: #ffffff;\">กราฟฟิก</span> (GPU)&nbsp;Intel UHD Graphics 617</li>\r\n<li>หน้าจอ (Display) :&nbsp;จอภาพ Retina&nbsp;จอภาพแบ็คไลท์แบบ LED ขนาด 13.3 นิ้ว (แนวทแยง) พร้อมเทคโนโลยี IPS ความละเอียดปกติ 2560 x 1600 ที่ 227 พิกเซลต่อนิ้ว พร้อมรองรับการแสดงสีสันหลายล้านสี</li>\r\n<li>แบตเตอรี่ : ความจุ 49.9 (Wh)</li>\r\n<li>การชาร์จและการพอร์ตเชื่อมต่อ : พอร์ต Thunderbolt 3 (USB‑C) จำนวน 2 พอร์ต</li>\r\n</ul>', NULL, 14000.00, NULL, '1746586752_MacbookAir1.1.webp', NULL, NULL, 'published', 0, '2025-05-05 09:48:17', '2025-11-05 09:59:06'),
(121, 121, 1, 'macbook-pro-15-2017', 'Macbook Pro 15”(2017)', '<h3 class=\"\" data-start=\"332\" data-end=\"364\"><strong data-start=\"339\" data-end=\"362\">หน่วยประมวลผล (CPU)</strong></h3>\r\n<ul data-start=\"384\" data-end=\"588\">\r\n<li class=\"\" data-start=\"384\" data-end=\"447\">\r\n<p class=\"\" data-start=\"386\" data-end=\"447\">Intel Core i7 แบบ 4 คอร์ 2.8GHz (Turbo Boost สูงสุด 3.8GHz)</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"590\" data-end=\"593\">\r\n<h3 class=\"\" data-start=\"595\" data-end=\"625\"><strong data-start=\"602\" data-end=\"623\">หน่วยความจำ (RAM)</strong></h3>\r\n<ul data-start=\"626\" data-end=\"689\">\r\n<li class=\"\" data-start=\"626\" data-end=\"689\">\r\n<p class=\"\" data-start=\"628\" data-end=\"689\">ขนาด: 16GB LPDDR3 2133MHz&nbsp;</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"691\" data-end=\"694\">\r\n<h3 class=\"\" data-start=\"696\" data-end=\"732\"><strong data-start=\"703\" data-end=\"730\">พื้นที่เก็บข้อมูล (HDD)</strong></h3>\r\n<ul data-start=\"733\" data-end=\"820\">\r\n<li class=\"\" data-start=\"733\" data-end=\"772\">\r\n<p class=\"\" data-start=\"735\" data-end=\"772\">HDD 256 GB</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"822\" data-end=\"825\">\r\n<h3 class=\"\" data-start=\"827\" data-end=\"852\"><strong data-start=\"834\" data-end=\"850\">กราฟิก (GPU)</strong></h3>\r\n<ul>\r\n<li data-start=\"1431\" data-end=\"1458\">Intel HD Graphics <a href=\"tel:630 1536\">630 1536</a> MB</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1512\" data-end=\"1515\">\r\n<p><strong style=\"font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Oxygen, Ubuntu, Cantarell, \'Open Sans\', \'Helvetica Neue\', sans-serif;\" data-start=\"990\" data-end=\"1010\">หน้าจอ (Display)</strong></p>\r\n<ul data-start=\"1013\" data-end=\"1180\">\r\n<li class=\"\" data-start=\"1013\" data-end=\"1039\">\r\n<p class=\"\" data-start=\"1015\" data-end=\"1039\">ขนาด: 15.4 นิ้ว Retina</p>\r\n</li>\r\n<li class=\"\" data-start=\"1040\" data-end=\"1085\">\r\n<p class=\"\" data-start=\"1042\" data-end=\"1085\">ความละเอียด: 2880 x 1800 พิกเซล&nbsp;</p>\r\n</li>\r\n<li class=\"\" data-start=\"1086\" data-end=\"1109\">\r\n<p class=\"\" data-start=\"1088\" data-end=\"1109\">ความสว่าง: 500 nits</p>\r\n</li>\r\n<li class=\"\" data-start=\"1110\" data-end=\"1141\">\r\n<p class=\"\" data-start=\"1112\" data-end=\"1141\">รองรับ: P3 wide color gamu</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1182\" data-end=\"1185\">\r\n<h3 class=\"\" data-start=\"1187\" data-end=\"1209\"><strong data-start=\"1194\" data-end=\"1207\">คีย์บอร์ด</strong></h3>\r\n<ul data-start=\"1210\" data-end=\"1323\">\r\n<li class=\"\" data-start=\"1210\" data-end=\"1242\">\r\n<p class=\"\" data-start=\"1212\" data-end=\"1242\">Butterfly keyboard รุ่นที่ 2</p>\r\n</li>\r\n<li class=\"\" data-start=\"1243\" data-end=\"1259\">\r\n<p class=\"\" data-start=\"1245\" data-end=\"1259\">มีไฟ backlit</p>\r\n</li>\r\n<li class=\"\" data-start=\"1260\" data-end=\"1291\">\r\n<p class=\"\" data-start=\"1262\" data-end=\"1291\">มี Touch Bar พร้อม Touch ID</p>\r\n</li>\r\n<li class=\"\" data-start=\"1292\" data-end=\"1323\">\r\n<p class=\"\" data-start=\"1294\" data-end=\"1323\">แทร็คแพด Force Touch ขนาดใหญ่</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1325\" data-end=\"1328\">\r\n<h3 class=\"\" data-start=\"1330\" data-end=\"1352\"><strong data-start=\"1337\" data-end=\"1350\">ระบบเสียง</strong></h3>\r\n<ul data-start=\"1353\" data-end=\"1424\">\r\n<li class=\"\" data-start=\"1353\" data-end=\"1379\">\r\n<p class=\"\" data-start=\"1355\" data-end=\"1379\">ลำโพงสเตอริโอคุณภาพสูง</p>\r\n</li>\r\n<li class=\"\" data-start=\"1380\" data-end=\"1424\">\r\n<p class=\"\" data-start=\"1382\" data-end=\"1424\">มีไมโครโฟน 3 ตัวสำหรับการรับเสียงที่ดีขึ้น</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1426\" data-end=\"1429\">\r\n<h3 class=\"\" data-start=\"1431\" data-end=\"1458\"><strong data-start=\"1438\" data-end=\"1456\">พอร์ตเชื่อมต่อ</strong></h3>\r\n<ul data-start=\"1459\" data-end=\"1510\">\r\n<li class=\"\" data-start=\"1459\" data-end=\"1487\">\r\n<p class=\"\" data-start=\"1461\" data-end=\"1487\">4x Thunderbolt 3 (USB-C)</p>\r\n</li>\r\n<li class=\"\" data-start=\"1488\" data-end=\"1510\">\r\n<p class=\"\" data-start=\"1490\" data-end=\"1510\">1x ช่องหูฟัง 3.5 มม.</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1512\" data-end=\"1515\">\r\n<h3 class=\"\" data-start=\"1517\" data-end=\"1539\"><strong data-start=\"1524\" data-end=\"1537\">แบตเตอรี่</strong></h3>\r\n<ul data-start=\"1540\" data-end=\"1644\">\r\n<li class=\"\" data-start=\"1540\" data-end=\"1559\">\r\n<p class=\"\" data-start=\"1542\" data-end=\"1559\">ความจุ: 76.0 Wh</p>\r\n</li>\r\n</ul>', '<h3 data-start=\"74\" data-end=\"102\">💻 <strong data-start=\"81\" data-end=\"100\">Processor (CPU)</strong></h3>\r\n<ul data-start=\"103\" data-end=\"162\">\r\n<li data-start=\"103\" data-end=\"162\">\r\n<p data-start=\"105\" data-end=\"162\">Intel Core i7, 4 cores, 2.8GHz (Turbo Boost up to 3.8GHz)</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"169\" data-end=\"194\">🧠 <strong data-start=\"176\" data-end=\"192\">Memory (RAM)</strong></h3>\r\n<ul data-start=\"195\" data-end=\"226\">\r\n<li data-start=\"195\" data-end=\"226\">\r\n<p data-start=\"197\" data-end=\"226\">Capacity: 16GB LPDDR3 2133MHz</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"233\" data-end=\"259\">💾 <strong data-start=\"240\" data-end=\"257\">Storage (HDD)</strong></h3>\r\n<ul data-start=\"260\" data-end=\"272\">\r\n<li data-start=\"260\" data-end=\"272\">\r\n<p data-start=\"262\" data-end=\"272\">HDD: 256GB</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"279\" data-end=\"306\">🎮 <strong data-start=\"286\" data-end=\"304\">Graphics (GPU)</strong></h3>\r\n<ul data-start=\"307\" data-end=\"359\">\r\n<li data-start=\"307\" data-end=\"359\">\r\n<p data-start=\"309\" data-end=\"359\">Intel HD Graphics 630 with 1536MB of shared memory</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"366\" data-end=\"386\">📺 <strong data-start=\"373\" data-end=\"384\">Display</strong></h3>\r\n<ul data-start=\"387\" data-end=\"513\">\r\n<li data-start=\"387\" data-end=\"421\">\r\n<p data-start=\"389\" data-end=\"421\">Size: 15.4-inch Retina display</p>\r\n</li>\r\n<li data-start=\"422\" data-end=\"456\">\r\n<p data-start=\"424\" data-end=\"456\">Resolution: 2880 x 1800 pixels</p>\r\n</li>\r\n<li data-start=\"457\" data-end=\"481\">\r\n<p data-start=\"459\" data-end=\"481\">Brightness: 500 nits</p>\r\n</li>\r\n<li data-start=\"482\" data-end=\"513\">\r\n<p data-start=\"484\" data-end=\"513\">Supports: P3 wide color gamut</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"520\" data-end=\"541\">🎹 <strong data-start=\"527\" data-end=\"539\">Keyboard</strong></h3>\r\n<ul data-start=\"542\" data-end=\"653\">\r\n<li data-start=\"542\" data-end=\"579\">\r\n<p data-start=\"544\" data-end=\"579\">2nd-generation Butterfly keyboard</p>\r\n</li>\r\n<li data-start=\"580\" data-end=\"596\">\r\n<p data-start=\"582\" data-end=\"596\">Backlit keys</p>\r\n</li>\r\n<li data-start=\"597\" data-end=\"624\">\r\n<p data-start=\"599\" data-end=\"624\">Touch Bar with Touch ID</p>\r\n</li>\r\n<li data-start=\"625\" data-end=\"653\">\r\n<p data-start=\"627\" data-end=\"653\">Large Force Touch trackpad</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"660\" data-end=\"685\">🔊 <strong data-start=\"667\" data-end=\"683\">Audio System</strong></h3>\r\n<ul data-start=\"686\" data-end=\"765\">\r\n<li data-start=\"686\" data-end=\"718\">\r\n<p data-start=\"688\" data-end=\"718\">High-quality stereo speakers</p>\r\n</li>\r\n<li data-start=\"719\" data-end=\"765\">\r\n<p data-start=\"721\" data-end=\"765\">Three microphones for improved voice capture</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"772\" data-end=\"790\">🔌 <strong data-start=\"779\" data-end=\"788\">Ports</strong></h3>\r\n<ul data-start=\"791\" data-end=\"851\">\r\n<li data-start=\"791\" data-end=\"825\">\r\n<p data-start=\"793\" data-end=\"825\">4x Thunderbolt 3 (USB-C) ports</p>\r\n</li>\r\n<li data-start=\"826\" data-end=\"851\">\r\n<p data-start=\"828\" data-end=\"851\">1x 3.5mm headphone jack</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"858\" data-end=\"878\">🔋 <strong data-start=\"865\" data-end=\"876\">Battery</strong></h3>\r\n<ul data-start=\"879\" data-end=\"984\">\r\n<li data-start=\"879\" data-end=\"900\">\r\n<p data-start=\"881\" data-end=\"900\">Capacity: 76.0 Wh</p>\r\n</li>\r\n</ul>', 18500.00, NULL, '/uploads/shop/2025/11/1762340320_1746585694_MacbookPro2.2.webp', NULL, NULL, 'published', 0, '2025-05-06 03:31:20', '2026-06-11 12:33:24'),
(122, 122, 1, 'macbook-pro-16-2019-a2141-cmns', 'MacBook Pro 16” 2019 (A2141) CMNS !!', '<h3 class=\"\" data-start=\"332\" data-end=\"364\"><strong data-start=\"339\" data-end=\"362\">หน่วยประมวลผล </strong><strong data-start=\"87\" data-end=\"106\">(CPU)</strong></h3>\r\n<ul data-start=\"384\" data-end=\"588\">\r\n<li class=\"\" data-start=\"384\" data-end=\"447\">\r\n<p class=\"\" data-start=\"386\" data-end=\"447\">Intel Core i7 แบบ 6 คอร์ ความเร็ว 2.6GHz (Turbo Boost สูงสุด 4.5GHz))</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"590\" data-end=\"593\">\r\n<h3 class=\"\" data-start=\"595\" data-end=\"625\"><strong data-start=\"602\" data-end=\"623\">หน่วยความจำ (RAM)</strong></h3>\r\n<ul data-start=\"626\" data-end=\"689\">\r\n<li class=\"\" data-start=\"626\" data-end=\"689\">\r\n<p class=\"\" data-start=\"628\" data-end=\"689\">16GB DDR4 2666MHz</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"691\" data-end=\"694\">\r\n<h3 class=\"\" data-start=\"696\" data-end=\"732\"><strong data-start=\"703\" data-end=\"730\">พื้นที่เก็บข้อมูล (SSD)</strong></h3>\r\n<ul data-start=\"733\" data-end=\"820\">\r\n<li class=\"\" data-start=\"733\" data-end=\"772\">\r\n<p class=\"\" data-start=\"735\" data-end=\"772\">SSD 512GB</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"822\" data-end=\"825\">\r\n<h3 class=\"\" data-start=\"827\" data-end=\"852\"><strong data-start=\"834\" data-end=\"850\">กราฟิก (GPU)</strong></h3>\r\n<ul>\r\n<li data-start=\"1431\" data-end=\"1458\">AMD Radeon Pro 5300M / 5500M</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1512\" data-end=\"1515\">\r\n<p><strong style=\"font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Oxygen, Ubuntu, Cantarell, \'Open Sans\', \'Helvetica Neue\', sans-serif;\" data-start=\"990\" data-end=\"1010\">หน้าจอ (Display)</strong></p>\r\n<ul>\r\n<li data-start=\"667\" data-end=\"703\"><strong data-start=\"667\" data-end=\"676\">ขนาด:</strong> Retina Display ขนาด 16 นิ้ว</li>\r\n<li data-start=\"704\" data-end=\"743\">\r\n<p data-start=\"706\" data-end=\"743\"><strong data-start=\"706\" data-end=\"722\">ความละเอียด:</strong> 3072x1920 พิกเซล</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1325\" data-end=\"1328\">\r\n<h3 class=\"\" data-start=\"1330\" data-end=\"1352\"><strong data-start=\"1337\" data-end=\"1350\">ระบบเสียง</strong></h3>\r\n<ul>\r\n<li data-start=\"1084\" data-end=\"1117\"><strong>ลำโพง</strong> : 6 ตัว</li>\r\n<li data-start=\"1118\" data-end=\"1159\">\r\n<p data-start=\"1120\" data-end=\"1159\"><strong data-start=\"1120\" data-end=\"1133\">ระบบเสียง : </strong>Dolby Atmos</p>\r\n</li>\r\n<li data-start=\"1160\" data-end=\"1198\">\r\n<p data-start=\"1162\" data-end=\"1198\"><strong data-start=\"1162\" data-end=\"1172\">ไมโครโฟน :</strong> ระบบเสียงระดับสตูดิโอ</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1426\" data-end=\"1429\">\r\n<h3 class=\"\" data-start=\"1431\" data-end=\"1458\"><strong data-start=\"1438\" data-end=\"1456\">พอร์ตเชื่อมต่อ</strong></h3>\r\n<ul>\r\n<li data-start=\"1001\" data-end=\"1033\">4x พอร์ต Thunderbolt 3 (USB-C)</li>\r\n<li data-start=\"1034\" data-end=\"1053\">\r\n<p data-start=\"1036\" data-end=\"1053\">ช่องหูฟัง 3.5 มม.</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1512\" data-end=\"1515\">\r\n<h3 class=\"\" data-start=\"1517\" data-end=\"1539\"><strong data-start=\"1524\" data-end=\"1537\">แบตเตอรี่</strong></h3>\r\n<ul>\r\n<li data-start=\"1542\" data-end=\"1559\">ความจุ 100 Wh</li>\r\n</ul>', '<h3 class=\"\" data-start=\"332\" data-end=\"364\"><strong data-start=\"339\" data-end=\"362\">Processor </strong><strong data-start=\"87\" data-end=\"106\">(CPU)</strong></h3>\r\n<ul data-start=\"384\" data-end=\"588\">\r\n<li class=\"\" data-start=\"384\" data-end=\"447\">\r\n<p class=\"\" data-start=\"386\" data-end=\"447\">Intel Core i7, 6-core, 2.6GHz (Turbo Boost up to 4.5GHz)</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"590\" data-end=\"593\">\r\n<h3 class=\"\" data-start=\"595\" data-end=\"625\"><strong data-start=\"602\" data-end=\"623\">Memory (RAM)</strong></h3>\r\n<ul data-start=\"626\" data-end=\"689\">\r\n<li class=\"\" data-start=\"626\" data-end=\"689\">\r\n<p class=\"\" data-start=\"628\" data-end=\"689\">16GB DDR4 2666MHz</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"691\" data-end=\"694\">\r\n<h3 class=\"\" data-start=\"696\" data-end=\"732\"><strong data-start=\"703\" data-end=\"730\">Storage (SSD)</strong></h3>\r\n<ul data-start=\"733\" data-end=\"820\">\r\n<li class=\"\" data-start=\"733\" data-end=\"772\">\r\n<p class=\"\" data-start=\"735\" data-end=\"772\">SSD 512GB</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"822\" data-end=\"825\">\r\n<h3 class=\"\" data-start=\"827\" data-end=\"852\"><strong data-start=\"834\" data-end=\"850\">Graphics (GPU)</strong></h3>\r\n<ul>\r\n<li data-start=\"1431\" data-end=\"1458\">AMD Radeon Pro 5300M / 5500M</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1512\" data-end=\"1515\">\r\n<p><strong>Display</strong></p>\r\n<ul>\r\n<li data-start=\"667\" data-end=\"703\">Size: 16-inch Retina Display</li>\r\n<li data-start=\"704\" data-end=\"743\">\r\n<p data-start=\"706\" data-end=\"743\">Resolution: 3072x1920 pixels</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1325\" data-end=\"1328\">\r\n<h3 class=\"\" data-start=\"1330\" data-end=\"1352\">Audio System</h3>\r\n<ul>\r\n<li data-start=\"1084\" data-end=\"1117\">Speakers: 6-speaker system</li>\r\n<li data-start=\"1118\" data-end=\"1159\">\r\n<p data-start=\"1120\" data-end=\"1159\">Audio: Dolby Atmos support</p>\r\n</li>\r\n<li data-start=\"1160\" data-end=\"1198\">\r\n<p data-start=\"1162\" data-end=\"1198\">Microphone: Studio-quality microphone array</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1426\" data-end=\"1429\">\r\n<h3 class=\"\" data-start=\"1431\" data-end=\"1458\">Ports &amp; Connectivity</h3>\r\n<ul>\r\n<li data-start=\"1001\" data-end=\"1033\">4x Thunderbolt 3 ports (USB-C)</li>\r\n<li data-start=\"1034\" data-end=\"1053\">\r\n<p data-start=\"1036\" data-end=\"1053\">1x 3.5mm headphone jack</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1512\" data-end=\"1515\">\r\n<h3 class=\"\" data-start=\"1517\" data-end=\"1539\">Battery</h3>\r\n<ul>\r\n<li>Capacity: 100 Wh</li>\r\n</ul>', 22000.00, 24000.00, '/uploads/shop/2025/11/1762339864_1746587887_MacBookPro3.1.webp', NULL, NULL, 'published', 0, '2025-05-07 03:18:07', '2026-06-11 12:33:24'),
(123, 123, 3, 'ipad-air-gen4-256-gb-sold', 'iPad Air Gen4  256 GB. —SOLD', '<p data-start=\"225\" data-end=\"256\"><strong>ชิปประมวลผล</strong></p>\r\n<ul>\r\n<li data-start=\"225\" data-end=\"256\">CPU: Apple A14 Bionic (5nm) 6-core (2 core ประสิทธิภาพสูง + 4 core ประหยัดพลังงาน)</li>\r\n<li data-start=\"223\" data-end=\"315\">\r\n<p data-start=\"225\" data-end=\"256\">GPU: Apple GPU แบบ 4-core</p>\r\n</li>\r\n<li data-start=\"348\" data-end=\"430\">\r\n<p data-start=\"350\" data-end=\"430\">Neural Engine: 16-core (สำหรับ Machine Learning เช่น Face Detection, AR ฯลฯ)</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"566\" data-end=\"569\">\r\n<h3 data-start=\"571\" data-end=\"584\">หน้าจอ</h3>\r\n<ul data-start=\"585\" data-end=\"848\">\r\n<li data-start=\"585\" data-end=\"608\">\r\n<p data-start=\"587\" data-end=\"608\">ขนาด: 10.9 นิ้ว</p>\r\n</li>\r\n<li data-start=\"609\" data-end=\"658\">\r\n<p data-start=\"611\" data-end=\"658\">ความละเอียด: 2360 x 1640 พิกเซล (264 ppi)</p>\r\n</li>\r\n<li data-start=\"659\" data-end=\"704\">\r\n<p data-start=\"661\" data-end=\"704\">ชนิด: Liquid Retina Display (IPS LCD)</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"850\" data-end=\"853\">\r\n<h3 data-start=\"855\" data-end=\"867\">กล้อง</h3>\r\n<h4 data-start=\"868\" data-end=\"883\">กล้องหลัง:</h4>\r\n<ul data-start=\"884\" data-end=\"1058\">\r\n<li data-start=\"884\" data-end=\"918\">\r\n<p data-start=\"886\" data-end=\"918\">ความละเอียด 12MP, รูรับแสง f/1.8</p>\r\n</li>\r\n<li data-start=\"919\" data-end=\"1022\">\r\n<p data-start=\"921\" data-end=\"935\">ถ่ายวิดีโอได้:</p>\r\n<ul data-start=\"938\" data-end=\"1022\">\r\n<li data-start=\"938\" data-end=\"963\">\r\n<p data-start=\"940\" data-end=\"963\">4K @ 24 / 30 / 60 fps</p>\r\n</li>\r\n<li data-start=\"966\" data-end=\"989\">\r\n<p data-start=\"968\" data-end=\"989\">1080p @ 30 / 60 fps</p>\r\n</li>\r\n<li data-start=\"992\" data-end=\"1022\">\r\n<p data-start=\"994\" data-end=\"1022\">slo-mo 1080p @ 120 / 240 fps</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1023\" data-end=\"1058\">\r\n<p data-start=\"1025\" data-end=\"1058\">มี Auto HDR, Panorama, Time-Lapse</p>\r\n</li>\r\n</ul>\r\n<h4 data-start=\"1060\" data-end=\"1075\">กล้องหน้า:</h4>\r\n<ul data-start=\"1076\" data-end=\"1186\">\r\n<li data-start=\"1076\" data-end=\"1111\">\r\n<p data-start=\"1078\" data-end=\"1111\">ความละเอียด 7MP, รูรับแสง f/2.0</p>\r\n</li>\r\n<li data-start=\"1112\" data-end=\"1137\">\r\n<p data-start=\"1114\" data-end=\"1137\">วิดีโอ 1080p @ 60 fps</p>\r\n</li>\r\n<li data-start=\"1138\" data-end=\"1186\">\r\n<p data-start=\"1140\" data-end=\"1186\">รองรับ FaceTime HD และ Center Framing (บางแอป)</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"1188\" data-end=\"1191\">\r\n<h3 data-start=\"1193\" data-end=\"1209\">แบตเตอรี่</h3>\r\n<ul data-start=\"1210\" data-end=\"1314\">\r\n<li data-start=\"1210\" data-end=\"1240\">\r\n<p data-start=\"1212\" data-end=\"1240\">ความจุ: 28.6 Wh (7606 mAh)</p>\r\n</li>\r\n<li data-start=\"1280\" data-end=\"1314\">\r\n<p data-start=\"1282\" data-end=\"1314\">ชาร์จเร็วผ่าน USB-C (รองรับ 20W)</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"1316\" data-end=\"1319\">\r\n<h3 data-start=\"1321\" data-end=\"1357\">พอร์ตเชื่อมต่อ &amp; การเชื่อมต่อ</h3>\r\n<ul data-start=\"1358\" data-end=\"1535\">\r\n<li data-start=\"1358\" data-end=\"1412\">\r\n<p data-start=\"1360\" data-end=\"1412\">USB-C (แทน Lightning) &ndash; ความเร็ว USB 3.1 Gen 1</p>\r\n</li>\r\n<li data-start=\"1413\" data-end=\"1439\">\r\n<p data-start=\"1415\" data-end=\"1439\">Wi-Fi 6 (802.11ax)</p>\r\n</li>\r\n<li data-start=\"1440\" data-end=\"1461\">\r\n<p data-start=\"1442\" data-end=\"1461\">Bluetooth 5.0</p>\r\n</li>\r\n<li data-start=\"1462\" data-end=\"1506\">\r\n<p data-start=\"1464\" data-end=\"1506\">eSIM + Nano SIM (เฉพาะรุ่น Cellular)</p>\r\n</li>\r\n<li data-start=\"1507\" data-end=\"1535\">\r\n<p data-start=\"1509\" data-end=\"1535\">ไม่มีช่องหูฟัง 3.5 มม.</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"1537\" data-end=\"1540\">\r\n<h3 data-start=\"1542\" data-end=\"1560\">ความปลอดภัย</h3>\r\n<ul data-start=\"1561\" data-end=\"1607\">\r\n<li data-start=\"1561\" data-end=\"1607\">\r\n<p data-start=\"1563\" data-end=\"1607\">Touch ID ฝังในปุ่ม Power (ด้านบนเครื่อง)</p>\r\n</li>\r\n</ul>', '<p data-start=\"44\" data-end=\"65\"><strong data-start=\"47\" data-end=\"65\">Processor Chip</strong></p>\r\n<p data-start=\"67\" data-end=\"290\"><strong data-start=\"67\" data-end=\"74\">CPU</strong>: Apple A14 Bionic (5nm), 6-core (2 high-performance cores + 4 energy-efficient cores)<br data-start=\"160\" data-end=\"163\"><strong data-start=\"163\" data-end=\"170\">GPU</strong>: Apple 4-core GPU<br data-start=\"188\" data-end=\"191\"><strong data-start=\"191\" data-end=\"208\">Neural Engine</strong>: 16-core Neural Engine (for machine learning tasks like face detection, AR, etc.)</p>\r\n<p data-start=\"292\" data-end=\"306\"><strong data-start=\"295\" data-end=\"306\">Display</strong></p>\r\n<p data-start=\"308\" data-end=\"420\"><strong data-start=\"308\" data-end=\"316\">Size</strong>: 10.9 inches<br data-start=\"329\" data-end=\"332\"><strong data-start=\"332\" data-end=\"346\">Resolution</strong>: 2360 x 1640 pixels (264 ppi)<br data-start=\"376\" data-end=\"379\"><strong data-start=\"379\" data-end=\"387\">Type</strong>: Liquid Retina Display (IPS LCD)</p>\r\n<p data-start=\"422\" data-end=\"436\"><strong data-start=\"425\" data-end=\"436\">Cameras</strong></p>\r\n<p data-start=\"438\" data-end=\"456\"><strong data-start=\"438\" data-end=\"453\">Rear Camera</strong>:</p>\r\n<ul data-start=\"457\" data-end=\"648\">\r\n<li data-start=\"457\" data-end=\"492\">\r\n<p data-start=\"459\" data-end=\"492\">12MP resolution, f/1.8 aperture</p>\r\n</li>\r\n<li data-start=\"493\" data-end=\"605\">\r\n<p data-start=\"495\" data-end=\"513\">Video recording:</p>\r\n<ul data-start=\"516\" data-end=\"605\">\r\n<li data-start=\"516\" data-end=\"542\">\r\n<p data-start=\"518\" data-end=\"542\">4K at 24 / 30 / 60 fps</p>\r\n</li>\r\n<li data-start=\"545\" data-end=\"569\">\r\n<p data-start=\"547\" data-end=\"569\">1080p at 30 / 60 fps</p>\r\n</li>\r\n<li data-start=\"572\" data-end=\"605\">\r\n<p data-start=\"574\" data-end=\"605\">Slo-mo 1080p at 120 / 240 fps</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"606\" data-end=\"648\">\r\n<p data-start=\"608\" data-end=\"648\">Features: Auto HDR, Panorama, Time-Lapse</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"650\" data-end=\"669\"><strong data-start=\"650\" data-end=\"666\">Front Camera</strong>:</p>\r\n<ul data-start=\"670\" data-end=\"793\">\r\n<li data-start=\"670\" data-end=\"704\">\r\n<p data-start=\"672\" data-end=\"704\">7MP resolution, f/2.0 aperture</p>\r\n</li>\r\n<li data-start=\"705\" data-end=\"731\">\r\n<p data-start=\"707\" data-end=\"731\">Video: 1080p at 60 fps</p>\r\n</li>\r\n<li data-start=\"732\" data-end=\"793\">\r\n<p data-start=\"734\" data-end=\"793\">Supports FaceTime HD and Center Framing (on supported apps)</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"795\" data-end=\"809\"><strong data-start=\"798\" data-end=\"809\">Battery</strong></p>\r\n<p data-start=\"795\" data-end=\"809\"><strong data-start=\"811\" data-end=\"823\">Capacity</strong>: 28.6 Wh (7606 mAh)<br data-start=\"884\" data-end=\"887\"><strong data-start=\"887\" data-end=\"899\">Charging</strong>: Fast charging via USB-C (supports 20W)</p>\r\n<p data-start=\"941\" data-end=\"968\"><strong data-start=\"944\" data-end=\"968\">Ports &amp; Connectivity</strong></p>\r\n<ul data-start=\"970\" data-end=\"1132\">\r\n<li data-start=\"970\" data-end=\"1022\">\r\n<p data-start=\"972\" data-end=\"1022\">USB-C (replaces Lightning) &ndash; USB 3.1 Gen 1 speed</p>\r\n</li>\r\n<li data-start=\"1023\" data-end=\"1045\">\r\n<p data-start=\"1025\" data-end=\"1045\">Wi-Fi 6 (802.11ax)</p>\r\n</li>\r\n<li data-start=\"1046\" data-end=\"1063\">\r\n<p data-start=\"1048\" data-end=\"1063\">Bluetooth 5.0</p>\r\n</li>\r\n<li data-start=\"1064\" data-end=\"1106\">\r\n<p data-start=\"1066\" data-end=\"1106\">eSIM + Nano SIM (Cellular models only)</p>\r\n</li>\r\n<li data-start=\"1107\" data-end=\"1132\">\r\n<p data-start=\"1109\" data-end=\"1132\">No 3.5mm headphone jack</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1134\" data-end=\"1149\"><strong data-start=\"1137\" data-end=\"1149\">Security</strong></p>\r\n<ul data-start=\"1151\" data-end=\"1193\">\r\n<li data-start=\"1151\" data-end=\"1193\">\r\n<p data-start=\"1153\" data-end=\"1193\">Touch ID built into the top power button</p>\r\n</li>\r\n</ul>', 9000.00, 9500.00, '/uploads/shop/2025/11/1762338027_1759314405_IMG_5751.jpeg', NULL, NULL, 'published', 0, '2025-05-12 06:35:58', '2026-06-11 12:33:24'),
(124, 124, 4, 'imac-m1-24-2021-sold', 'iMac M1  24” 2021 —SOLD', '<p class=\"\" data-start=\"132\" data-end=\"230\"><strong data-start=\"135\" data-end=\"158\">หน่วยประมวลผล (CPU)</strong><br data-start=\"158\" data-end=\"161\">&bull; Apple M1 (8-core CPU &ndash; 4 คอร์ประสิทธิภาพสูง + 4 คอร์ประหยัดพลังงาน)</p>\r\n<p class=\"\" data-start=\"232\" data-end=\"315\"><strong data-start=\"235\" data-end=\"256\">หน่วยความจำ (RAM)</strong><br data-start=\"256\" data-end=\"259\">&bull; 8GB&nbsp; Unified Memory&nbsp;</p>\r\n<p class=\"\" data-start=\"317\" data-end=\"396\"><strong data-start=\"320\" data-end=\"347\">พื้นที่เก็บข้อมูล (SSD)</strong><br data-start=\"347\" data-end=\"350\">&bull; SSD 512GB</p>\r\n<p class=\"\" data-start=\"485\" data-end=\"608\"><strong data-start=\"488\" data-end=\"507\">จอภาพ (Display)</strong><br data-start=\"507\" data-end=\"510\">&bull; Retina 4.5K ขนาด 24 นิ้ว<br data-start=\"536\" data-end=\"539\">&bull; ความละเอียด 4480 x 2520 พิกเซล<br data-start=\"571\" data-end=\"574\">&bull; รองรับ P3 wide color + True Tone</p>\r\n<p class=\"\" data-start=\"610\" data-end=\"696\"><strong data-start=\"613\" data-end=\"635\">กล้องหน้า (Webcam)</strong><br data-start=\"635\" data-end=\"638\">&bull; กล้อง FaceTime HD 1080p<br data-start=\"663\" data-end=\"666\">&bull; ไมโครโฟนระดับสตูดิโอ (3 ตัว)</p>\r\n<p class=\"\" data-start=\"698\" data-end=\"792\"><strong data-start=\"701\" data-end=\"718\">เสียง (Audio)</strong><br data-start=\"718\" data-end=\"721\">&bull; ลำโพง 6 ตัว ระบบเสียงรอบทิศทาง<br data-start=\"753\" data-end=\"756\">&bull; รองรับ Spatial Audio + Dolby Atmos</p>\r\n<p data-start=\"871\" data-end=\"986\"><strong data-start=\"874\" data-end=\"900\">พอร์ตเชื่อมต่อ (Ports)</strong><br data-start=\"900\" data-end=\"903\">&bull; 2x Thunderbolt&nbsp;<br data-start=\"941\" data-end=\"944\">&bull; 2x USB type - C</p>\r\n<p data-start=\"988\" data-end=\"1098\"><strong data-start=\"991\" data-end=\"1007\">อุปกรณ์เสริม</strong><br data-start=\"1007\" data-end=\"1010\">&bull; Magic Keyboard&nbsp;<br data-start=\"1054\" data-end=\"1057\">&bull; Magic Mouse&nbsp;</p>', '<p data-start=\"44\" data-end=\"146\"><strong data-start=\"47\" data-end=\"66\">Processor (CPU)</strong><br data-start=\"66\" data-end=\"69\">&bull; Apple M1 (8-core CPU &ndash; 4 high-performance cores + 4 energy-efficient cores)</p>\r\n<p data-start=\"148\" data-end=\"190\"><strong data-start=\"151\" data-end=\"167\">Memory (RAM)</strong><br data-start=\"167\" data-end=\"170\">&bull; 8GB Unified Memory</p>\r\n<p data-start=\"192\" data-end=\"226\"><strong data-start=\"195\" data-end=\"212\">Storage (SSD)</strong><br data-start=\"212\" data-end=\"215\">&bull; 512GB SSD</p>\r\n<p data-start=\"266\" data-end=\"388\"><strong data-start=\"269\" data-end=\"280\">Display</strong><br data-start=\"280\" data-end=\"283\">&bull; 24-inch Retina 4.5K display<br data-start=\"312\" data-end=\"315\">&bull; Resolution: 4480 x 2520 pixels<br data-start=\"347\" data-end=\"350\">&bull; Supports P3 wide color and True Tone</p>\r\n<p data-start=\"390\" data-end=\"489\"><strong data-start=\"393\" data-end=\"418\">Front Camera (Webcam)</strong><br data-start=\"418\" data-end=\"421\">&bull; 1080p FaceTime HD camera<br data-start=\"447\" data-end=\"450\">&bull; Studio-quality three-microphone array</p>\r\n<p data-start=\"491\" data-end=\"576\"><strong data-start=\"494\" data-end=\"503\">Audio</strong><br data-start=\"503\" data-end=\"506\">&bull; Six-speaker sound system with spatial audio<br data-start=\"551\" data-end=\"554\">&bull; Supports Dolby Atmos</p>\r\n<p data-start=\"578\" data-end=\"627\"><strong data-start=\"581\" data-end=\"590\">Ports</strong><br data-start=\"590\" data-end=\"593\">&bull; 2x Thunderbolt<br data-start=\"609\" data-end=\"612\">&bull; 2x USB Type-C</p>\r\n<p data-start=\"629\" data-end=\"682\"><strong data-start=\"632\" data-end=\"647\">Accessories</strong><br data-start=\"647\" data-end=\"650\">&bull; Magic Keyboard<br data-start=\"666\" data-end=\"669\">&bull; Magic Mouse</p>', 29500.00, NULL, '/uploads/shop/2025/11/1762337471_1759402009_IMG_5841.jpeg', NULL, NULL, 'published', 0, '2025-05-14 09:09:11', '2026-06-11 12:33:24'),
(125, 125, 7, 'magic-trackpad', 'Magic TrackPad (มือสอง)', '<ul>\r\n<li>🖱 เทคโนโลยีสัมผัส :&nbsp;<span style=\"font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Oxygen, Ubuntu, Cantarell, \'Open Sans\', \'Helvetica Neue\', sans-serif;\">Multi‑Touch + Force Touch</span></li>\r\n<li>📏ขนาดแทร็กแพด : 16.0 x 11.49 ซม.</li>\r\n<li>⚖️ น้ำหนัก :~230 กรัม</li>\r\n<li>🌟พื้นผิว : กระจกเรียบ</li>\r\n<li>🔗การเชื่อมต่อ : Bluetooth</li>\r\n<li>🔋แบตเตอรี่ : ลิเธียมไอออนในตัว</li>\r\n<li>🔌 พอร์ตชาร์จ : Lightning</li>\r\n</ul>', '<ul>\r\n<li>🖱 <strong data-start=\"41\" data-end=\"61\">Touch Technology</strong>: Multi‑Touch + Force Touch</li>\r\n<li>📏 <strong data-start=\"94\" data-end=\"111\">Trackpad Size</strong>: 16.0 x 11.49 cm</li>\r\n<li>⚖️ <strong data-start=\"134\" data-end=\"144\">Weight</strong>: ~230 grams</li>\r\n<li>🌟 <strong data-start=\"162\" data-end=\"173\">Surface</strong>: Smooth glass</li>\r\n<li>🔗 <strong data-start=\"193\" data-end=\"209\">Connectivity</strong>: Bluetooth</li>\r\n<li>🔋 <strong data-start=\"226\" data-end=\"237\">Battery</strong>: Built-in lithium-ion</li>\r\n<li>🔌 <strong data-start=\"265\" data-end=\"282\">Charging Port</strong>: Lightning</li>\r\n</ul>', 3200.00, NULL, '/uploads/shop/2025/11/1762336722_1759486617_IMG_5859.jpeg', NULL, NULL, 'published', 0, '2025-05-15 05:26:40', '2026-06-11 12:33:24'),
(126, 126, 7, 'magic-keyboard', 'Magic Keyboard (มือสอง)', '<p>&nbsp;</p>\r\n<p>ขนาดและน้ำหนัก<br>ความสูง: 0.41&ndash;1.09 ซม.<br>ความกว้าง: 27.89 ซม.<br>ความลึก: 11.49 ซม.<br>น้ำหนัก: 0.239 กก.*<br>ทั่วไป<br>ปุ่มมัลติมีเดีย<br>การเชื่อมต่อและการต่อขยาย<br>Bluetooth<br>พอร์ต USB-C<br>ไร้สาย</p>\r\n<p>&nbsp;</p>', '<p><br>Size and Weight<br>&nbsp; &nbsp; &bull; &nbsp; &nbsp;Height: 0.41&ndash;1.09 cm<br>&nbsp; &nbsp; &bull; &nbsp; &nbsp;Width: 27.89 cm<br>&nbsp; &nbsp; &bull; &nbsp; &nbsp;Depth: 11.49 cm<br>&nbsp; &nbsp; &bull; &nbsp; &nbsp;Weight: 0.239 kg*</p>\r\n<p>General<br>&nbsp; &nbsp; &bull; &nbsp; &nbsp;Multimedia keys</p>\r\n<p>Connectivity and Expansion<br>&nbsp; &nbsp; &bull; &nbsp; &nbsp;Bluetooth<br>&nbsp; &nbsp; &bull; &nbsp; &nbsp;USB-C port<br>&nbsp; &nbsp; &bull; &nbsp; &nbsp;Wireless</p>', 2500.00, NULL, '/uploads/shop/2025/11/1762332206_1759403619_IMG_5850.jpeg', NULL, NULL, 'published', 0, '2025-05-16 04:16:35', '2026-06-11 12:33:24'),
(127, 127, 7, 'hoco-usb-c-to-lightning', 'สายชาร์จ hoco USB-C To Lightning', '<ul>\r\n<li>\r\n<p><strong>จอแสดงผลดิจิทัล (Digital Display):</strong> มาพร้อมหน้าจอแสดงผล LED ในตัวที่หัวชาร์จ ช่วยให้คุณตรวจสอบกำลังไฟ (วัตต์) ที่กำลังชาร์จได้อย่างชัดเจนและเรียลไทม์</p>\r\n</li>\r\n<li>\r\n<p><strong>รองรับกำลังไฟสูงสุด 27W (PD - Power Delivery):</strong> ให้การชาร์จที่รวดเร็วและมีประสิทธิภาพสำหรับอุปกรณ์ Apple ของคุณ (iPhone/iPad) ที่รองรับเทคโนโลยี Power Delivery</p>\r\n</li>\r\n<li>\r\n<p><strong>การเชื่อมต่อ:</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Input:</strong> USB-C (Type-C)</p>\r\n</li>\r\n<li>\r\n<p><strong>Output:</strong> Lightning (สำหรับอุปกรณ์ Apple เช่น iPhone, iPad)</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>ความยาวสาย:</strong> 1.2m/3.9ft</p>\r\n</li>\r\n<li>\r\n<p><strong>วัสดุคุณภาพสูง:</strong> ผลิตจากวัสดุที่ทนทาน เพื่อการใช้งานที่ยาวนานและป้องกันการหักงอ</p>\r\n</li>\r\n<li>\r\n<p><strong>การชาร์จและซิงค์ข้อมูล:</strong> ไม่เพียงแต่ชาร์จไฟได้อย่างรวดเร็ว แต่ยังสามารถใช้ในการถ่ายโอนข้อมูลระหว่างอุปกรณ์กับคอมพิวเตอร์ได้อย่างราบรื่น</p>\r\n</li>\r\n<li>\r\n<p><strong>ดีไซน์ทันสมัย:</strong> ออกแบบมาให้มีความเรียบง่ายแต่ดูดี เหมาะสมกับการใช้งานในชีวิตประจำวัน</p>\r\n</li>\r\n</ul>\r\n<p><strong>เหมาะสำหรับ:</strong></p>\r\n<ul>\r\n<li>\r\n<p>ผู้ที่ต้องการสายชาร์จ iPhone/iPad ที่มีประสิทธิภาพสูง</p>\r\n</li>\r\n<li>\r\n<p>ผู้ที่ต้องการตรวจสอบสถานะการชาร์จแบบเรียลไทม์</p>\r\n</li>\r\n<li>\r\n<p>ผู้ที่มองหาสายชาร์จที่รองรับเทคโนโลยี Power Delivery (PD)</p>\r\n</li>\r\n<li>\r\n<p>ผู้ที่ต้องการสายชาร์จที่ทนทานและใช้งานได้ยาวนาน</p>\r\n</li>\r\n</ul>\r\n<p><strong>ข้อแนะนำการใช้งาน:</strong></p>\r\n<ul>\r\n<li>\r\n<p>เพื่อประสิทธิภาพการชาร์จสูงสุด ควรใช้งานร่วมกับอะแดปเตอร์ชาร์จที่รองรับกำลังไฟ 27W หรือสูงกว่า และมีพอร์ต USB-C ที่รองรับ PD</p>\r\n</li>\r\n</ul>', '<ul>\r\n<li>\r\n<p><strong>Digital Display:</strong> Equipped with a built-in LED display on the connector, allowing you to clearly monitor the real-time charging power (watts).</p>\r\n</li>\r\n<li>\r\n<p><strong>Supports Up to 27W Power (PD - Power Delivery):</strong> Provides fast and efficient charging for your Power Delivery-compatible Apple devices (iPhone/iPad).</p>\r\n</li>\r\n<li>\r\n<p><strong>Connectivity:</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Input:</strong> USB-C (Type-C)</p>\r\n</li>\r\n<li>\r\n<p><strong>Output:</strong> Lightning (for Apple devices like iPhone, iPad)</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Cable Length:</strong> (Please check the actual cable length specified on the product box, e.g., 1.2 meters or 2 meters, for accuracy.)</p>\r\n</li>\r\n<li>\r\n<p><strong>High-Quality Material:</strong> Made from durable materials for long-lasting use and to prevent bending or breakage.</p>\r\n</li>\r\n<li>\r\n<p><strong>Charging and Data Sync:</strong> Not only charges quickly but also enables seamless data transfer between your device and computer.</p>\r\n</li>\r\n<li>\r\n<p><strong>Modern Design:</strong> Designed with a simple yet elegant look, suitable for everyday use.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Ideal For:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Users who need a high-performance charging cable for iPhone/iPad.</p>\r\n</li>\r\n<li>\r\n<p>Those who want to monitor real-time charging status.</p>\r\n</li>\r\n<li>\r\n<p>Individuals looking for a charging cable that supports Power Delivery (PD) technology.</p>\r\n</li>\r\n<li>\r\n<p>Anyone seeking a durable and long-lasting charging cable.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Usage Recommendation:</strong></p>\r\n<ul>\r\n<li>\r\n<p>For optimal charging performance, use with a USB-C PD-compatible power adapter that supports 27W or higher.</p>\r\n</li>\r\n</ul>', 350.00, NULL, '1752061887__Hoco..webp', NULL, NULL, 'published', 0, '2025-07-09 11:51:27', '2025-11-05 08:38:08'),
(128, 128, 7, 'hoco-usb-c-to-c', 'สายชาร์จ hoco USB-C To C', '<ul>\r\n<li>\r\n<p><strong>จอแสดงผลดิจิทัล (Digital Display):</strong> มาพร้อมหน้าจอแสดงผล LED ในตัวที่หัวชาร์จ ช่วยให้คุณตรวจสอบกำลังไฟ (วัตต์) ที่กำลังชาร์จได้อย่างชัดเจนและเรียลไทม์</p>\r\n</li>\r\n<li>\r\n<p><strong>รองรับกำลังไฟสูงสุด 100W (PD - Power Delivery):</strong> ให้การชาร์จที่รวดเร็วและมีประสิทธิภาพสูงสำหรับอุปกรณ์หลากหลายประเภทที่รองรับพอร์ต USB-C และเทคโนโลยี Power Delivery ไม่ว่าจะเป็น โน้ตบุ๊ก, แท็บเล็ต, สมาร์ทโฟน</p>\r\n</li>\r\n<li>\r\n<p><strong>การเชื่อมต่อ:</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Input:</strong> USB-C (Type-C)</p>\r\n</li>\r\n<li>\r\n<p><strong>Output:</strong> USB-C (Type-C)</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>ความยาวสาย:</strong> 1.2m/3.9ft</p>\r\n</li>\r\n<li>\r\n<p><strong>วัสดุคุณภาพสูง:</strong> ผลิตจากวัสดุที่ทนทาน เพื่อการใช้งานที่ยาวนานและป้องกันการหักงอ</p>\r\n</li>\r\n<li>\r\n<p><strong>การชาร์จและซิงค์ข้อมูล:</strong> ไม่เพียงแต่ชาร์จไฟได้อย่างรวดเร็ว แต่ยังสามารถใช้ในการถ่ายโอนข้อมูลระหว่างอุปกรณ์กับคอมพิวเตอร์ได้อย่างราบรื่น</p>\r\n</li>\r\n<li>\r\n<p><strong>ดีไซน์ทันสมัย:</strong> ออกแบบมาให้มีความเรียบง่ายแต่ดูดี เหมาะสมกับการใช้งานในชีวิตประจำวัน</p>\r\n</li>\r\n</ul>\r\n<p><strong>เหมาะสำหรับ:</strong></p>\r\n<ul>\r\n<li>\r\n<p>ผู้ที่ต้องการสายชาร์จ USB-C to USB-C ที่มีประสิทธิภาพสูง</p>\r\n</li>\r\n<li>\r\n<p>ผู้ที่ต้องการตรวจสอบสถานะการชาร์จแบบเรียลไทม์</p>\r\n</li>\r\n<li>\r\n<p>ผู้ที่มองหาสายชาร์จที่รองรับกำลังไฟสูงถึง 100W สำหรับโน้ตบุ๊ก, แท็บเล็ต, และสมาร์ทโฟน</p>\r\n</li>\r\n<li>\r\n<p>ผู้ที่ต้องการสายชาร์จที่ทนทานและใช้งานได้ยาวนาน</p>\r\n</li>\r\n</ul>\r\n<p><strong>ข้อแนะนำการใช้งาน:</strong></p>\r\n<ul>\r\n<li>\r\n<p>เพื่อให้ได้ประสิทธิภาพการชาร์จ 100W ควรใช้งานร่วมกับอะแดปเตอร์ชาร์จที่รองรับกำลังไฟ 100W หรือสูงกว่า และมีพอร์ต USB-C ที่รองรับ PD</p>\r\n</li>\r\n</ul>', '<ul>\r\n<li>\r\n<p><strong>Digital Display:</strong> Equipped with a built-in LED display on the connector, allowing you to clearly monitor the real-time charging power (watts).</p>\r\n</li>\r\n<li>\r\n<p><strong>Supports Up to 100W Power (PD - Power Delivery):</strong> Provides fast and highly efficient charging for a wide range of devices that support USB-C ports and Power Delivery technology, including laptops, tablets, and smartphones.</p>\r\n</li>\r\n<li>\r\n<p><strong>Connectivity:</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Input:</strong> USB-C (Type-C)</p>\r\n</li>\r\n<li>\r\n<p><strong>Output:</strong> USB-C (Type-C)</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Cable Length:</strong> (Please check the actual cable length specified on the product box, e.g., 1.2 meters or 2 meters, for accuracy.)</p>\r\n</li>\r\n<li>\r\n<p><strong>High-Quality Material:</strong> Made from durable materials for long-lasting use and to prevent bending or breakage.</p>\r\n</li>\r\n<li>\r\n<p><strong>Charging and Data Sync:</strong> Not only charges quickly but also enables seamless data transfer between your device and computer.</p>\r\n</li>\r\n<li>\r\n<p><strong>Modern Design:</strong> Designed with a simple yet elegant look, suitable for everyday use.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Ideal For:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Users who need a high-performance USB-C to USB-C charging cable.</p>\r\n</li>\r\n<li>\r\n<p>Those who want to monitor real-time charging status.</p>\r\n</li>\r\n<li>\r\n<p>Individuals looking for a charging cable that supports high power up to 100W for laptops, tablets, and smartphones.</p>\r\n</li>\r\n<li>\r\n<p>Anyone seeking a durable and long-lasting charging cable.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Usage Recommendation:</strong></p>\r\n<ul>\r\n<li>\r\n<p>To achieve 100W charging performance, use with a USB-C PD-compatible power adapter that supports 100W or higher.</p>\r\n</li>\r\n</ul>', 350.00, NULL, '/uploads/shop/2025/11/1762331873_1752116877__Hoco_100W.webp', NULL, NULL, 'published', 0, '2025-07-10 03:07:57', '2026-06-11 12:33:24'),
(129, 129, 1, 'macbook-air-13-2020-sold', 'MacBook Air 13”(2020)—SOLD', '<h3 class=\"\" data-start=\"332\" data-end=\"364\"><strong data-start=\"339\" data-end=\"362\">หน่วยประมวลผล </strong><strong data-start=\"87\" data-end=\"106\">(CPU)</strong></h3>\r\n<ul data-start=\"384\" data-end=\"588\">\r\n<li class=\"\" data-start=\"384\" data-end=\"447\">\r\n<p class=\"\" data-start=\"386\" data-end=\"447\">Intel Core i7 แบบ Quad-core ความเร็ว 1.2GHz (Turbo Boost สูงสุด 3.8GHz)</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"590\" data-end=\"593\">\r\n<h3 class=\"\" data-start=\"595\" data-end=\"625\"><strong data-start=\"602\" data-end=\"623\">หน่วยความจำ (RAM)</strong></h3>\r\n<ul data-start=\"626\" data-end=\"689\">\r\n<li class=\"\" data-start=\"626\" data-end=\"689\">\r\n<p class=\"\" data-start=\"628\" data-end=\"689\">16GB แบบ LPDDR4X ความเร็ว 3733MHz</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"691\" data-end=\"694\">\r\n<h3 class=\"\" data-start=\"696\" data-end=\"732\"><strong data-start=\"703\" data-end=\"730\">พื้นที่เก็บข้อมูล (SSD)</strong></h3>\r\n<ul data-start=\"733\" data-end=\"820\">\r\n<li class=\"\" data-start=\"733\" data-end=\"772\">\r\n<p class=\"\" data-start=\"735\" data-end=\"772\">SSD 512GB</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"822\" data-end=\"825\">\r\n<h3 class=\"\" data-start=\"827\" data-end=\"852\"><strong data-start=\"834\" data-end=\"850\">กราฟิก (GPU)</strong></h3>\r\n<ul>\r\n<li data-start=\"1431\" data-end=\"1458\">Intel Iris Plus Graphics 1536 MB</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1512\" data-end=\"1515\">\r\n<p><strong style=\"font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Oxygen, Ubuntu, Cantarell, \'Open Sans\', \'Helvetica Neue\', sans-serif;\" data-start=\"990\" data-end=\"1010\">หน้าจอ (Display)</strong></p>\r\n<ul data-start=\"1013\" data-end=\"1180\">\r\n<li class=\"\" data-start=\"1013\" data-end=\"1039\">\r\n<p class=\"\" data-start=\"1015\" data-end=\"1039\">ขนาด: 13.3 นิ้ว Retina Display</p>\r\n</li>\r\n<li class=\"\" data-start=\"1040\" data-end=\"1085\">\r\n<p class=\"\" data-start=\"1042\" data-end=\"1085\">ความละเอียด 2560 x 1600 พิกเซล</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1182\" data-end=\"1185\">\r\n<h3 class=\"\" data-start=\"1187\" data-end=\"1209\"><strong data-start=\"1194\" data-end=\"1207\">คีย์บอร์ด</strong></h3>\r\n<ul data-start=\"1210\" data-end=\"1323\">\r\n<li class=\"\" data-start=\"1210\" data-end=\"1242\">Magic Keyboard (กลไกแบบ Scissor switch) พร้อมไฟ Backlit</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1325\" data-end=\"1328\">\r\n<h3 class=\"\" data-start=\"1330\" data-end=\"1352\"><strong data-start=\"1337\" data-end=\"1350\">ระบบเสียง</strong></h3>\r\n<ul data-start=\"1353\" data-end=\"1424\">\r\n<li class=\"\" data-start=\"1353\" data-end=\"1379\">\r\n<p class=\"\" data-start=\"1355\" data-end=\"1379\">ลำโพงสเตอริโอ</p>\r\n</li>\r\n<li class=\"\" data-start=\"1380\" data-end=\"1424\">\r\n<p class=\"\" data-start=\"1382\" data-end=\"1424\">มีไมโครโฟน 3 ตัวสำหรับการรับเสียงที่ดีขึ้น</p>\r\n</li>\r\n<li class=\"\" data-start=\"1380\" data-end=\"1424\">รองรับเสียง Dolby Atmos</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1426\" data-end=\"1429\">\r\n<h3 class=\"\" data-start=\"1431\" data-end=\"1458\"><strong data-start=\"1438\" data-end=\"1456\">พอร์ตเชื่อมต่อ</strong></h3>\r\n<ul data-start=\"1459\" data-end=\"1510\">\r\n<li class=\"\" data-start=\"1459\" data-end=\"1487\">\r\n<p class=\"\" data-start=\"1461\" data-end=\"1487\">2x Thunderbolt 3 (USB-C)</p>\r\n</li>\r\n<li class=\"\" data-start=\"1488\" data-end=\"1510\">\r\n<p class=\"\" data-start=\"1490\" data-end=\"1510\">1x ช่องหูฟัง 3.5 มม.</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1512\" data-end=\"1515\">\r\n<h3 class=\"\" data-start=\"1517\" data-end=\"1539\"><strong data-start=\"1524\" data-end=\"1537\">แบตเตอรี่</strong></h3>\r\n<ul data-start=\"1540\" data-end=\"1644\">\r\n<li class=\"\" data-start=\"1540\" data-end=\"1559\">\r\n<p class=\"\" data-start=\"1542\" data-end=\"1559\">ความจุ: 49.9 &nbsp; Wh</p>\r\n</li>\r\n</ul>\r\n<p>&nbsp;</p>', '<h3 class=\"\" data-start=\"332\" data-end=\"364\"><strong data-start=\"87\" data-end=\"106\">Processor (CPU)</strong></h3>\r\n<ul data-start=\"384\" data-end=\"588\">\r\n<li class=\"\" data-start=\"384\" data-end=\"447\">\r\n<p class=\"\" data-start=\"386\" data-end=\"447\">Intel Core i7 Quad-core 1.2GHz (Turbo Boost up to 3.8GHz)</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"590\" data-end=\"593\">\r\n<h3 class=\"\" data-start=\"595\" data-end=\"625\"><strong data-start=\"171\" data-end=\"187\">Memory (RAM)</strong></h3>\r\n<ul data-start=\"626\" data-end=\"689\">\r\n<li class=\"\" data-start=\"626\" data-end=\"689\">\r\n<p class=\"\" data-start=\"628\" data-end=\"689\">16GB LPDDR4X at 3733MHz</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"691\" data-end=\"694\">\r\n<h3 class=\"\" data-start=\"696\" data-end=\"732\"><strong data-start=\"703\" data-end=\"730\">Storage (SSD)</strong></h3>\r\n<ul data-start=\"733\" data-end=\"820\">\r\n<li class=\"\" data-start=\"733\" data-end=\"772\">\r\n<p class=\"\" data-start=\"735\" data-end=\"772\">SSD 512GB</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"822\" data-end=\"825\">\r\n<h3 class=\"\" data-start=\"827\" data-end=\"852\"><strong data-start=\"252\" data-end=\"270\">Graphics (GPU)</strong></h3>\r\n<ul>\r\n<li data-start=\"1431\" data-end=\"1458\">Intel Iris Plus Graphics 1536 MB</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1512\" data-end=\"1515\">\r\n<p><strong data-start=\"310\" data-end=\"321\">Display</strong></p>\r\n<ul data-start=\"1013\" data-end=\"1180\">\r\n<li class=\"\" data-start=\"1013\" data-end=\"1039\">\r\n<p class=\"\" data-start=\"1015\" data-end=\"1039\">Size: 13.3-inch Retina Display<br data-start=\"354\" data-end=\"357\">Resolution: 2560 x 1600 pixels</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1182\" data-end=\"1185\">\r\n<h3 class=\"\" data-start=\"1187\" data-end=\"1209\"><strong data-start=\"392\" data-end=\"404\">Keyboard</strong></h3>\r\n<ul data-start=\"1210\" data-end=\"1323\">\r\n<li class=\"\" data-start=\"1210\" data-end=\"1242\">\r\n<p data-start=\"389\" data-end=\"468\">Magic Keyboard with Scissor Switch mechanism and Backlit keys</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1325\" data-end=\"1328\">\r\n<h3 class=\"\" data-start=\"1330\" data-end=\"1352\"><strong data-start=\"473\" data-end=\"482\">Audio</strong></h3>\r\n<ul>\r\n<li data-start=\"1355\" data-end=\"1379\">Stereo speakers</li>\r\n<li data-start=\"1355\" data-end=\"1379\">Three-microphone array for better voice capture</li>\r\n<li data-start=\"1355\" data-end=\"1379\">Supports Dolby Atmos audio</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1426\" data-end=\"1429\">\r\n<h3 class=\"\" data-start=\"1431\" data-end=\"1458\"><strong data-start=\"584\" data-end=\"593\">Ports</strong></h3>\r\n<ul data-start=\"1459\" data-end=\"1510\">\r\n<li class=\"\" data-start=\"1459\" data-end=\"1487\">\r\n<p class=\"\" data-start=\"1461\" data-end=\"1487\">2x Thunderbolt 3 (USB-C)</p>\r\n</li>\r\n<li class=\"\" data-start=\"1459\" data-end=\"1487\">\r\n<p class=\"\" data-start=\"1461\" data-end=\"1487\">1x 3.5mm headphone jack</p>\r\n</li>\r\n</ul>\r\n<hr class=\"\" data-start=\"1512\" data-end=\"1515\">\r\n<h3 class=\"\" data-start=\"1517\" data-end=\"1539\">Battery</h3>\r\n<ul data-start=\"1540\" data-end=\"1644\">\r\n<li class=\"\" data-start=\"1540\" data-end=\"1559\">\r\n<p class=\"\" data-start=\"1542\" data-end=\"1559\">Capacity: 49.9 Wh</p>\r\n</li>\r\n</ul>', 15000.00, NULL, '/uploads/shop/2025/11/1762331745_1759397199_IMG_5828.jpeg', NULL, NULL, 'published', 0, '2025-07-12 06:04:04', '2026-06-11 12:33:24');
